# CRX VOS — D2 class library (@import in every diagram)

vars: {
  bg:        "#0B0F14"
  elevated:  "#111820"
  text:      "#E8EDF4"
  muted:     "#8B9BB4"
  cyan:      "#00D4FF"
  blue:      "#3B82F6"
  purple:    "#A855F7"
  green:     "#22D3A5"
  red:       "#F87171"
  gray:      "#64748B"
  stroke:    "#2A3444"
}

classes: {
  agent: {
    shape: rectangle
    style.fill: "${elevated}"
    style.stroke: "${blue}"
    style.font-color: "${text}"
    style.border-radius: 8
  }
  memory: {
    shape: cylinder
    style.fill: "#1a1033"
    style.stroke: "${purple}"
    style.font-color: "${text}"
  }
  event: {
    shape: circle
    style.fill: "${bg}"
    style.stroke: "${cyan}"
    style.font-color: "${cyan}"
  }
  engine: {
    shape: hexagon
    style.fill: "${elevated}"
    style.stroke: "${blue}"
    style.font-color: "${text}"
  }
  external: {
    shape: parallelogram
    style.fill: "${elevated}"
    style.stroke: "${gray}"
    style.font-color: "${muted}"
  }
  truth: {
    shape: cylinder
    style.fill: "${elevated}"
    style.stroke: "${green}"
    style.font-color: "${text}"
  }
  replay: {
    shape: rectangle
    style.fill: "#1a1033"
    style.stroke: "${purple}"
    style.font-color: "${text}"
    style.border-radius: 8
  }
  past: {
    shape: circle
    style.fill: "${elevated}"
    style.stroke: "${gray}"
    style.font-color: "${muted}"
  }
  exec: {
    shape: rectangle
    style.fill: "${elevated}"
    style.stroke: "${cyan}"
    style.font-color: "${cyan}"
    style.border-radius: 8
  }
  verify: {
    shape: rectangle
    style.fill: "${elevated}"
    style.stroke: "${green}"
    style.font-color: "${green}"
    style.border-radius: 8
  }
  fail: {
    style.stroke: "${red}"
    style.font-color: "${red}"
  }
  context: {
    style.fill: "#1a103320"
    style.stroke: "${purple}"
    style.stroke-dash: 4
  }
  snapshot: {
    shape: document
    style.fill: "${elevated}"
    style.stroke: "${green}"
    style.font-color: "${text}"
  }
}

{
  "foundationalId": "FD-01",
  "slug": "stateless-intelligence-engine",
  "version": "1.0.0",
  "diagramTitle": "Stateless Intelligence Engine",
  "diagramPurpose": "Show that the model is pure compute with no memory between invocations—every call starts from zero internal state.",
  "diagramType": "DT-02 Layered Architecture",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Render reasoning layer with blue stroke 2px; emphasize dashed boundary around engine with 4px purple stroke at 30% opacity for context frame (empty)."
  },
  "animation": {
    "phases": [
      { "id": "establish", "atSec": 0, "action": "Fade title + outer boundary" },
      { "id": "layers", "atSec": 1.2, "action": "Reveal layers top-to-bottom: Input → Engine → Output" },
      { "id": "emphasis", "atSec": 4, "action": "Pulse Engine node; dim Input/Output briefly" },
      { "id": "constraint", "atSec": 6, "action": "Flash 'No State' label on engine border" }
    ],
    "loop": null
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Title visible", "script": "This is a stateless intelligence engine." },
      { "atSec": 2, "visual": "Three layers shown", "script": "Prompt in, tokens out—nothing persists inside." },
      { "atSec": 5, "visual": "Engine pulsing", "script": "Each invocation is independent. No memory. No history." },
      { "atSec": 8, "visual": "No-state callout", "script": "That's powerful for reasoning—and insufficient for real systems." }
    ]
  },
  "assetCategory": { "primary": "AC-02", "secondary": ["AC-01", "AC-08"] }
}

@import ../../themes/d2-classes.d2

boundary: {
  label: ""
  style.stroke: "${stroke}"
  style.stroke-dash: 4

  input: Prompt Input { class: external }
  engine: Intelligence Engine { class: agent }
  output: Token Output { class: external }

  input -> engine -> output
}

no_state: No Internal State { class: fail }
engine -> no_state: "each call resets" {
  style.stroke-dash: 5
  style.stroke: "${red}"
}

{
  "foundationalId": "FD-02",
  "slug": "stateful-problem-space",
  "version": "1.0.0",
  "diagramTitle": "Stateful Problem Space",
  "diagramPurpose": "Contrast stateless compute against problems that require memory, persistence, coordination, and replay across time.",
  "diagramType": "DT-01 System Context",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-center",
    "legendPlacement": "bottom-left",
    "exportNotes": "Center engine smaller; surround with 5 purple/green nodes on radial layout. Use double-stroke boundary for Problem Space subgraph."
  },
  "animation": {
    "phases": [
      { "id": "establish", "atSec": 0, "action": "Show stateless engine center" },
      { "id": "surround", "atSec": 2, "action": "Reveal problem-space boundary frame" },
      { "id": "pillars", "atSec": 3.5, "action": "Stagger reveal: Memory, State, Replay, Coordination, Persistence" },
      { "id": "gap", "atSec": 7, "action": "Red dashed edges from engine to each pillar—'cannot solve alone'" }
    ],
    "loop": null
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Engine center", "script": "Stateless intelligence handles inference." },
      { "atSec": 3, "visual": "Boundary expands", "script": "Real problems live in a stateful space." },
      { "atSec": 6, "visual": "Five pillars appear", "script": "Memory, state, replay, coordination, persistence." },
      { "atSec": 10, "visual": "Red gap lines", "script": "The engine alone cannot hold these concerns." }
    ]
  },
  "assetCategory": { "primary": "AC-01", "secondary": ["AC-03", "AC-04", "AC-05"] }
}

@import ../../themes/d2-classes.d2

engine: Stateless Engine { class: agent }

problem_space: Stateful Problem Space {
  class: context

  memory: Memory { class: memory }
  state: Application State { class: context }
  replay: Replay { class: engine }
  coordination: Coordination { class: engine }
  persistence: Persistence { class: truth }
}

engine -> problem_space.memory: gap { style.stroke: "${red}"; style.stroke-dash: 5 }
engine -> problem_space.state: gap { style.stroke: "${red}"; style.stroke-dash: 5 }
engine -> problem_space.replay: gap { style.stroke: "${red}"; style.stroke-dash: 5 }
engine -> problem_space.coordination: gap { style.stroke: "${red}"; style.stroke-dash: 5 }
engine -> problem_space.persistence: gap { style.stroke: "${red}"; style.stroke-dash: 5 }

{
  "foundationalId": "FD-03",
  "slug": "execution-entropy",
  "version": "1.0.0",
  "diagramTitle": "Execution Entropy",
  "diagramPurpose": "Show how non-deterministic execution accumulates divergence over steps—each fork increases irrecoverable drift without external truth.",
  "diagramType": "DT-16 Entropy Accumulation",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Left-to-right timeline. Step 1 cyan; forks progressively redder stroke weight. No green nodes—entropy has no truth anchor yet."
  },
  "animation": {
    "phases": [
      { "id": "seed", "atSec": 0, "action": "Single cyan exec node at step 1" },
      { "id": "fork1", "atSec": 2, "action": "Branch to 2 paths at step 2" },
      { "id": "fork2", "atSec": 4, "action": "Each branch forks again—4 paths at step 3" },
      { "id": "entropy", "atSec": 6, "action": "Red pulse on outer branches; label 'Divergence'" }
    ],
    "loop": { "intervalSec": 3, "action": "Dash-offset animates along red branches" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Step 1 node", "script": "Execution starts deterministic." },
      { "atSec": 2.5, "visual": "First fork", "script": "One non-deterministic choice—and paths split." },
      { "atSec": 5, "visual": "Second fork", "script": "Entropy compounds with every uncontrolled branch." },
      { "atSec": 8, "visual": "Red divergence", "script": "Without replay and truth, you cannot reconstruct what happened." }
    ]
  },
  "assetCategory": { "primary": "AC-05", "secondary": ["AC-01", "AC-09"] }
}

@import ../../themes/d2-classes.d2

s1: Step 1 { class: exec }
s2a: Step 2a { class: exec }
s2b: Step 2b { class: exec; style.stroke: "${red}" }
s3a: Step 3a { class: exec; style.stroke: "${red}" }
s3b: Step 3b { class: fail }
s3c: Step 3c { class: fail }
s3d: Step 3d { class: fail }
divergence: Divergence { class: fail }

s1 -> s2a -> s3a
s1 -> s2b -> s3c
s2a -> s3b
s2b -> s3d
s3b -> divergence { style.stroke-dash: 5; style.stroke: "${red}" }
s3d -> divergence { style.stroke-dash: 5; style.stroke: "${red}" }

{
  "foundationalId": "FD-04",
  "slug": "context-collapse",
  "version": "1.0.0",
  "diagramTitle": "Context Collapse",
  "diagramPurpose": "Illustrate context window overflow—when accumulated tokens exceed the boundary, compression fails and critical information is lost.",
  "diagramType": "DT-10 Memory Hierarchy",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Context window as purple dashed double frame. Overflow items clip outside frame in red. Funnel node for compression between working memory and window."
  },
  "animation": {
    "phases": [
      { "id": "frame", "atSec": 0, "action": "Draw context window boundary" },
      { "id": "fill", "atSec": 1.5, "action": "Tokens fill window left-to-right" },
      { "id": "compress", "atSec": 4, "action": "Funnel pulses—compression attempt" },
      { "id": "collapse", "atSec": 6, "action": "Red overflow spill + 'Context Collapse' label" }
    ],
    "loop": null
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Window frame", "script": "Every model has a context window—a hard boundary." },
      { "atSec": 3, "visual": "Tokens filling", "script": "History, tools, and retrieval all compete for space." },
      { "atSec": 5, "visual": "Funnel active", "script": "Compression tries to fit more in." },
      { "atSec": 8, "visual": "Red overflow", "script": "When compression fails, context collapses—and decisions degrade." }
    ]
  },
  "assetCategory": { "primary": "AC-08", "secondary": ["AC-03", "AC-01"] }
}

@import ../../themes/d2-classes.d2

working: Working Memory { class: memory }
compress: Compression { class: engine }

context_window: Context Window {
  class: context
  t1: Token Block { class: context }
  t2: Token Block { class: context }
  t3: Token Block { class: context }
}

lost: Lost Context { class: fail }

working -> compress: retrieve { style.stroke: "${purple}" }
compress -> context_window.t1
context_window.t3 -> lost: overflow { style.stroke: "${red}"; style.stroke-dash: 5 }

{
  "foundationalId": "FD-05",
  "slug": "event-store",
  "version": "1.0.0",
  "diagramTitle": "Event Store",
  "diagramPurpose": "Show append-only event log as the committed truth source—commands become immutable events, never updated in place.",
  "diagramType": "DT-08 Event Sourcing",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Event store green cylinder center-left. Events as small cyan circles on dashed stream into store. No update arrows—append only."
  },
  "animation": {
    "phases": [
      { "id": "store", "atSec": 0, "action": "Reveal green Event Store cylinder" },
      { "id": "cmd", "atSec": 1.5, "action": "Command node appears" },
      { "id": "events", "atSec": 3, "action": "Events animate along cyan dashed path into store" },
      { "id": "truth", "atSec": 5.5, "action": "Green pulse on store—'Committed Truth'" }
    ],
    "loop": { "intervalSec": 4, "action": "New event circle travels stream into store" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Store visible", "script": "The event store is your source of truth." },
      { "atSec": 2, "visual": "Command appears", "script": "Commands don't mutate state directly." },
      { "atSec": 4, "visual": "Events flowing", "script": "They become immutable events—appended forever." },
      { "atSec": 7, "visual": "Green commit pulse", "script": "Once committed, the log is the history you can replay." }
    ]
  },
  "assetCategory": { "primary": "AC-04", "secondary": ["AC-01", "AC-05"] }
}

@import ../../themes/d2-classes.d2

handler: Command Handler { class: engine }
e1: "evt:1" { class: event }
e2: "evt:2" { class: event }
e3: "evt:3" { class: event }
store: Event Store { class: truth }

handler -> e1 -> e2 -> e3 -> store {
  style.stroke: "${cyan}"
  style.stroke-dash: 5
}

{
  "foundationalId": "FD-06",
  "slug": "memory-hierarchy",
  "version": "1.0.0",
  "diagramTitle": "Memory Hierarchy",
  "diagramPurpose": "Map cognition tiers from fast volatile working memory through semantic archives to procedural skill—each tier trades speed for capacity.",
  "diagramType": "DT-10 Memory Hierarchy",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Pyramid layout top=smallest/fastest. All memory nodes purple. Procedural as purple hexagon at base. Purple retrieval arrows downward."
  },
  "animation": {
    "phases": [
      { "id": "top", "atSec": 0, "action": "Working memory at apex" },
      { "id": "mid", "atSec": 2, "action": "Semantic archive tier expands" },
      { "id": "base", "atSec": 4, "action": "Procedural hexagon at base" },
      { "id": "flow", "atSec": 6, "action": "Purple retrieval arrows animate downward" }
    ],
    "loop": { "intervalSec": 5, "action": "Highlight one tier at a time in sequence" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Working memory", "script": "Working memory is fast, small, and volatile." },
      { "atSec": 3, "visual": "Semantic tier", "script": "Semantic memory holds facts and embeddings at scale." },
      { "atSec": 5, "visual": "Procedural base", "script": "Procedural memory encodes how—not what." },
      { "atSec": 8, "visual": "Retrieval arrows", "script": "Retrieval pulls from lower tiers into the context window." }
    ]
  },
  "assetCategory": { "primary": "AC-03", "secondary": ["AC-08", "AC-01"] }
}

@import ../../themes/d2-classes.d2

working: Working Memory { class: memory }
semantic: Semantic Archive { class: memory }
procedural: Procedural Memory { class: engine; style.stroke: "${purple}"; style.fill: "#1a1033" }
context: Context Window { class: context }

working -> semantic: promote { style.stroke: "${purple}" }
semantic -> context: retrieve { style.stroke: "${purple}" }
procedural -> context: skill recall { style.stroke: "${purple}" }
working -> semantic: evict { style.stroke-dash: 5; style.stroke: "${purple}" }

{
  "foundationalId": "FD-07",
  "slug": "replay-engine",
  "version": "1.0.0",
  "diagramTitle": "Replay Engine",
  "diagramPurpose": "Demonstrate replay grammar: read past events from truth store, re-execute through deterministic engine, compare against committed state.",
  "diagramType": "DT-09 Replay / Determinism",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Gray past events, purple replay path loop, cyan current exec, green truth store, red divergence branch. Snapshot as document node off store."
  },
  "animation": {
    "phases": [
      { "id": "store", "atSec": 0, "action": "Green Event Store + gray past events" },
      { "id": "replay", "atSec": 2, "action": "Purple loop animates from store to engine" },
      { "id": "exec", "atSec": 4, "action": "Cyan current execution path" },
      { "id": "verify", "atSec": 6, "action": "Green verify node—match or red divergence" }
    ],
    "loop": { "intervalSec": 4, "action": "Purple dash-offset on replay loop edge" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Store + past events", "script": "Past events live in the committed log—gray, immutable." },
      { "atSec": 2.5, "visual": "Purple replay loop", "script": "The replay engine re-feeds them through deterministic execution." },
      { "atSec": 5, "visual": "Cyan current path", "script": "Current execution runs in parallel—cyan." },
      { "atSec": 8, "visual": "Verify/diverge", "script": "Match means verified. Divergence means something broke determinism." }
    ]
  },
  "assetCategory": { "primary": "AC-05", "secondary": ["AC-04", "AC-01"] }
}

@import ../../themes/d2-classes.d2

store: Event Store { class: truth }
snapshot: Snapshot { class: snapshot }
p1: past { class: past }
p2: past { class: past }
replay: Replay Engine { class: replay }
current: Current Exec { class: exec }
verify: Verify { class: verify }
divergence: Divergence { class: fail }

store -> p1
store -> p2
store -> snapshot
p1 -> replay: "purple replay" { style.stroke: "${purple}" }
p2 -> replay: "purple replay" { style.stroke: "${purple}" }
replay -> current
current -> verify
verify -> store: match { style.stroke: "${green}" }
verify -> divergence: mismatch { style.stroke: "${red}"; style.stroke-dash: 5 }

{
  "foundationalId": "FD-08",
  "slug": "context-compiler",
  "version": "1.0.0",
  "diagramTitle": "Context Compiler",
  "diagramPurpose": "Show context assembly as a compile pipeline—retrieve, rank, compress, and inject into the context window before reasoning.",
  "diagramType": "DT-03 Data Flow",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Strict left-to-right pipeline. Purple arrows for retrieval. Funnel shape for compression. Final output enters purple context frame."
  },
  "animation": {
    "phases": [
      { "id": "sources", "atSec": 0, "action": "Memory + external sources left" },
      { "id": "retrieve", "atSec": 1.5, "action": "Purple retrieval arrows to ranker" },
      { "id": "compress", "atSec": 3.5, "action": "Funnel compression stage pulses" },
      { "id": "inject", "atSec": 5.5, "action": "Compiled context fills window; blue reasoning node activates" }
    ],
    "loop": { "intervalSec": 6, "action": "Token packet travels full pipeline left-to-right" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Sources", "script": "Context doesn't appear—it gets compiled." },
      { "atSec": 2, "visual": "Retrieval", "script": "Retrieve relevant memory with ranked scoring." },
      { "atSec": 4, "visual": "Compression", "script": "Compress to fit the window budget." },
      { "atSec": 6, "visual": "Reasoning", "script": "Inject into the frame—then the engine can reason." }
    ]
  },
  "assetCategory": { "primary": "AC-08", "secondary": ["AC-03", "AC-02"] }
}

@import ../../themes/d2-classes.d2

memory: Memory { class: memory }
external: External Docs { class: external }
retrieve: Retrieve { class: engine }
rank: Rank { class: engine }
compress: Compress { class: engine }

context_window: Context Window {
  class: context
  compiled: Compiled Context { class: context }
}

reasoning: Reasoning { class: agent }

memory -> retrieve: purple { style.stroke: "${purple}" }
external -> retrieve
retrieve -> rank -> compress -> context_window.compiled -> reasoning

{
  "foundationalId": "FD-09",
  "slug": "persistent-cognition-graph",
  "version": "1.0.0",
  "diagramTitle": "Persistent Cognition Graph",
  "diagramPurpose": "Model long-horizon cognition as a graph—nodes are concepts, edges are relationships, persisted across sessions and replayable over time.",
  "diagramType": "DT-13 Distributed Cognition",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-left",
    "legendPlacement": "bottom-right",
    "exportNotes": "Graph nodes as purple circles (concepts). Green store anchors bottom. Cyan events attach to edges. Agent queries graph via purple retrieval."
  },
  "animation": {
    "phases": [
      { "id": "graph", "atSec": 0, "action": "Reveal concept nodes + relationship edges" },
      { "id": "persist", "atSec": 2, "action": "Green store connects to all nodes" },
      { "id": "event", "atSec": 4, "action": "Cyan event circles land on edges—new relationships" },
      { "id": "query", "atSec": 6, "action": "Agent purple retrieval path highlights subgraph" }
    ],
    "loop": { "intervalSec": 5, "action": "Pulse one concept node and its neighbors" }
  },
  "voiceover": {
    "beats": [
      { "atSec": 0, "visual": "Graph mesh", "script": "Cognition over time becomes a graph of concepts and links." },
      { "atSec": 2.5, "visual": "Green store", "script": "Persistence anchors the graph across sessions." },
      { "atSec": 5, "visual": "Cyan events", "script": "Events add edges—experience becomes structure." },
      { "atSec": 8, "visual": "Agent query", "script": "Agents retrieve subgraphs—not isolated facts." }
    ]
  },
  "assetCategory": { "primary": "AC-03", "secondary": ["AC-04", "AC-13"] }
}

{
  "foundationalId": "FD-10",
  "slug": "distributed-cognition-system",
  "version": "1.0.0",
  "diagramTitle": "Distributed Cognition System",
  "diagramPurpose": "Show multiple agents coordinating through a shared memory bus—specialists read/write shared state without central bottleneck.",
  "diagramType": "DT-13 Distributed Cognition",
  "mermaidFile": "diagram.mmd",
  "d2File": "diagram.d2",
  "svgRendering": {
    "canvas": "1920x1080",
    "background": "#0B0F14",
    "dpi": 144,
    "safeMarginPx": 64,
    "titlePlacement": "top-center",
    "legendPlacement": "bottom-left",
    "exportNotes": "Hub memory bus purple cylinder center. 3-4 agent nodes radial. Bidirectional purple sync edges. Planner agent slightly larger blue node at top."
  },
  "animation": {
    "phases": [
      { "id": "bus", "atSec": 0, "action": "Purple Memory Bus center" },
